declarations.body:
fun n B factor matvec residual conversion forward backward update =>
  { factor := factor, matvec := matvec, residual := residual, conversion := conversion, forward := forward,
    backward := backward, update := update }

declarations.type:
∀ {n B : Nat} {factor : Fin B → MixedPrecisionBlockJacobi.Tape}
  {matvec residual conversion : Nat → Fin n → MixedPrecisionBlockJacobi.Tape}
  {forward backward : Nat → Fin B → MixedPrecisionBlockJacobi.Tape}
  {update : Nat → Fin n → MixedPrecisionBlockJacobi.Tape} {factor_1 : Fin B → MixedPrecisionBlockJacobi.Tape}
  {matvec_1 residual_1 conversion_1 : Nat → Fin n → MixedPrecisionBlockJacobi.Tape}
  {forward_1 backward_1 : Nat → Fin B → MixedPrecisionBlockJacobi.Tape}
  {update_1 : Nat → Fin n → MixedPrecisionBlockJacobi.Tape},
  Eq.{1}
      { factor := factor, matvec := matvec, residual := residual, conversion := conversion, forward := forward,
        backward := backward, update := update }
      { factor := factor_1, matvec := matvec_1, residual := residual_1, conversion := conversion_1,
        forward := forward_1, backward := backward_1, update := update_1 } →
    And (Eq.{1} factor factor_1)
      (And (Eq.{1} matvec matvec_1)
        (And (Eq.{1} residual residual_1)
          (And (Eq.{1} conversion conversion_1)
            (And (Eq.{1} forward forward_1) (And (Eq.{1} backward backward_1) (Eq.{1} update update_1))))))

declarations.body:
fun {n B} {P} {factor} {matvec residual conversion} {forward backward} {update} {factor'}
    {matvec' residual' conversion'} {forward' backward'} {update'} eq k =>
  id.{u} (MixedPrecisionBlockJacobi.Execution.noConfusion.{u} ⋯ ⋯ ⋯ k)

fun n S T us uc A D N R =>
  HAdd.hAdd.{0, 0, 0}
    (HAdd.hAdd.{0, 0, 0}
      (HDiv.hDiv.{0, 0, 0}
        (HAdd.hAdd.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} (MixedPrecisionBlockJacobi.eta T uc D R) us)
          (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 us)
            (HAdd.hAdd.{0, 0, 0} (MixedPrecisionBlockJacobi.q D N)
              (HMul.hMul.{0, 0, 0} uc (MixedPrecisionBlockJacobi.p D A)))))
        (HSub.hSub.{0, 0, 0} 1 (MixedPrecisionBlockJacobi.eta T uc D R)))
      us)
    (HDiv.hDiv.{0, 0, 0}
      (HMul.hMul.{0, 0, 0}
        (HMul.hMul.{0, 0, 0} (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 us) (HAdd.hAdd.{0, 0, 0} 1 uc))
          (MixedPrecisionBlockJacobi.c₁ n S us))
        (MixedPrecisionBlockJacobi.p D A))
      (HSub.hSub.{0, 0, 0} 1 (MixedPrecisionBlockJacobi.eta T uc D R)))

fun n S T us uc A D R x b =>
  HAdd.hAdd.{0, 0, 0}
    (HMul.hMul.{0, 0, 0}
      (HAdd.hAdd.{0, 0, 0} us
        (HDiv.hDiv.{0, 0, 0}
          (HMul.hMul.{0, 0, 0}
            (HMul.hMul.{0, 0, 0} (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 us) (HAdd.hAdd.{0, 0, 0} 1 uc))
              (MixedPrecisionBlockJacobi.c₁ n S us))
            (MixedPrecisionBlockJacobi.p D A))
          (HSub.hSub.{0, 0, 0} 1 (MixedPrecisionBlockJacobi.eta T uc D R))))
      (MixedPrecisionBlockJacobi.vectorInfNorm x))
    (HMul.hMul.{0, 0, 0}
      (HMul.hMul.{0, 0, 0}
        (HDiv.hDiv.{0, 0, 0}
          (HMul.hMul.{0, 0, 0} (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 us) (HAdd.hAdd.{0, 0, 0} 1 uc)) us)
          (HSub.hSub.{0, 0, 0} 1 (MixedPrecisionBlockJacobi.eta T uc D R)))
        (MixedPrecisionBlockJacobi.matrixInfNorm (Inv.inv.{0} D)))
      (MixedPrecisionBlockJacobi.vectorInfNorm b))

fun {T} t A R j =>
  have d := MixedPrecisionBlockJacobi.cholNumerator t A R j j;
  ite.{1} (LT.lt.{0} 0 d)
    (have z := MixedPrecisionBlockJacobi.rounded t (List.cons.{0} 2 List.nil.{0}) (Real.sqrt d);
    Option.some.{0} (Function.update.{1, 1} R j (Function.update.{1, 1} (R j) j z)))
    Option.none.{0}

fun {T} t A R i j =>
  ite.{1} (Eq.{1} (R i i) 0) Option.none.{0}
    (have z :=
      MixedPrecisionBlockJacobi.rounded t (List.cons.{0} 2 List.nil.{0})
        (HDiv.hDiv.{0, 0, 0} (MixedPrecisionBlockJacobi.cholNumerator t A R i j) (R i i));
    Option.some.{0} (Function.update.{1, 1} R i (Function.update.{1, 1} (R i) j z)))

fun {n B T} layout blocks E r k =>
  have rhs := MixedPrecisionBlockJacobi.convertedResidual E r k;
  have c := fun l =>
    have R := MixedPrecisionBlockJacobi.factorBlocks blocks E l;
    have y :=
      MixedPrecisionBlockJacobi.forwardSubstitution (MixedPrecisionBlockJacobi.Execution.forward E k l) R fun j =>
        rhs ((Equiv.symm.{1, 1} layout) (Prod.mk.{0, 0} l j));
    MixedPrecisionBlockJacobi.backwardSubstitution (MixedPrecisionBlockJacobi.Execution.backward E k l) R y;
  fun i => c (layout i).1 (layout i).2

fun {n B} S E A b v k =>
  have z := MixedPrecisionBlockJacobi.tiledMatvec S (MixedPrecisionBlockJacobi.Execution.matvec E k) A v;
  fun i =>
  MixedPrecisionBlockJacobi.rounded (MixedPrecisionBlockJacobi.Execution.residual E k i) List.nil.{0}
    (HSub.hSub.{0, 0, 0} (b i) (z i))

fun n S us =>
  HAdd.hAdd.{0, 0, 0}
    (HAdd.hAdd.{0, 0, 0}
      (MixedPrecisionBlockJacobi.gamma (HSub.hSub.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} S (HDiv.hDiv.{0, 0, 0} n S)) 1) us) us)
    (HMul.hMul.{0, 0, 0} us
      (MixedPrecisionBlockJacobi.gamma (HSub.hSub.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} S (HDiv.hDiv.{0, 0, 0} n S)) 1) us))

fun {n B T} layout S blocks E A b v k =>
  have r := MixedPrecisionBlockJacobi.computedResidual S E A b v k;
  have c := MixedPrecisionBlockJacobi.computedCorrection layout blocks E r k;
  fun i =>
  MixedPrecisionBlockJacobi.rounded (MixedPrecisionBlockJacobi.Execution.update E k i) List.nil.{0}
    (HAdd.hAdd.{0, 0, 0} (v i) (c i))
